contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable {
        require(amount > 0);

        uint balBeforeCall = address(c).balance;

        bool reverted;
        c.sendTo(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        assert(reverted || balAfter <= balBeforeCall);
    }
}

